// Generated by the e2e-perfromance-test-suite-k6 skill.
// The read-heavy, unauthenticated scenario the "TPS" and "Peak Load" NFRs
// are measured against: SmartBuy's actual browse path -- product list, then
// a random product's detail page.
import http from 'k6/http';
import { check, group } from 'k6';
import { apiUrl } from '../lib/http-client.js';

export function browseProducts() {
  group('browse_products', () => {
    const listRes = http.get(apiUrl('/api/products'), { tags: { name: 'GET /api/products' } });
    const listOk = check(listRes, { 'list products: 200': (r) => r.status === 200 });
    if (!listOk) return;

    const products = listRes.json();
    if (!products.length) return;
    const product = products[Math.floor(Math.random() * products.length)];

    http.get(apiUrl(`/api/products/${product.id}`), { tags: { name: 'GET /api/products/:id' } });
  });
}

// Allows `k6 run tests/browse-products.js` standalone at a fixed light rate.
export const options = {
  scenarios: {
    standalone: {
      executor: 'constant-arrival-rate',
      rate: 10,
      timeUnit: '1s',
      duration: '30s',
      preAllocatedVUs: 20,
      maxVUs: 50,
      exec: 'browseProducts',
    },
  },
  thresholds: {
    http_req_failed: ['rate<0.05'],
  },
};
